  function compactAmount(value){value=Number(value||0);if(value>=1000000000){return (value/1000000000).toFixed(value>=10000000000?1:2).replace(/\.0+$/,'')+'B';}if(value>=1000000){return (value/1000000).toFixed(value>=10000000?1:2).replace(/\.0+$/,'')+'M';}if(value>=1000){return (value/1000).toFixed(value>=10000?1:2).replace(/\.0+$/,'')+'K';}return String(Math.max(0,Math.floor(value)));}
  function stockHtml(farm){var s=farm.resource_snapshot;if(!s||['food','wood','steel','oil'].some(function(k){return s[k]===null||s[k]===undefined;})){return '<div class="stock-unavailable">'+esc(tr('stockUnavailable'))+'</div>';}return '<div class="stock-grid">'+['food','wood','steel','oil'].map(function(k){return '<span><small>'+esc(tr(k))+'</small><b>'+compactAmount(s[k])+'</b></span>';}).join('')+'</div>';}
