  function adminDashboardHomeHtml(){var summary=state.adminSummary,expired=adminSubscriptionRows('expired',0).length,archived=state.adminArchiveDirectory.reduce(function(total,group){return total+group[1].length;},0);return '<div class="admin-command-hero"><div><span class="region-badge">ADMIN CONTROL CENTER</span><h2>كل الإدارة من مكان واحد</h2><p>ابحث، أضف، عدّل، جدّد أو أوقف القلاع بدون كتابة أوامر طويلة.</p></div><span class="admin-command-mark">⌘</span></div><div class="admin-summary-grid"><div><small>القلاع</small><b>'+summary[0]+'</b></div><div><small>العملاء</small><b>'+summary[1]+'</b></div><div><small>الجاهزة</small><b>'+summary[2]+'</b></div><div class="admin-summary-alert"><small>في الأرشيف</small><b>'+archived+'</b></div></div><section class="section-card"><div class="admin-quick-search"><span>⌕</span><input id="adminHomeSearch" class="field" inputmode="numeric" value="'+esc(state.adminSearch)+'" placeholder="ابحث بمعرّف تيليجرام أو رقم القلعة"></div></section><div class="admin-module-grid">'+[['clients','👥','العملاء والقلاع','بحث سريع وحالة كل قلعة'],['subscriptions','◷','متابعة الاشتراكات','المنتهية والقريبة من الانتهاء'],['archive','▤','الأرشيف','استرجاع وتجديد القلاع المؤرشفة'],['add','＋','إضافة قلاع','حساب واحد أو عدة قلاع'],['renew','▣','تجديد الاشتراكات','بالأيام أو تاريخ من التقويم'],['edit','✎','تعديل قلعة','المالك والاشتراك والتشغيل'],['remove','⌫','حذف قلعة','تأكيد واضح قبل الحذف'],['operations','▶','تشغيل وإيقاف','لقلعة أو عميل كامل'],['servers','◈','السيرفرات','الحمل والخدمات والقلاع'],['reports','●','الحالة والتقارير','أونلاين ومهام واتصال']].map(function(item){return '<button class="admin-module" type="button" data-admin-nav="'+item[0]+'"><span>'+item[1]+'</span><div><b>'+item[2]+'</b><small>'+item[3]+'</small></div><i>‹</i></button>';}).join('')+'</div>';}
