  function adminSubscriptionRows(mode,days){var rows=[],today=adminTodayDay();state.adminDirectory.forEach(function(group){var telegram=String(group[0]),expiry=Array.isArray(group[2])?group[2]:[];group[1].forEach(function(castle,index){var value=Number(expiry[index]||0),endDay=adminExpiryDay(value),remaining=endDay===null?null:endDay-today,match=mode==='missing'?endDay===null:(mode==='expired'?remaining!==null&&remaining<0:remaining!==null&&remaining>=0&&remaining<=days);if(match){rows.push({telegram:telegram,castle:castle,end:adminExpiryText(value),remaining:remaining});}});});return rows.sort(function(a,b){if(a.remaining===b.remaining){return Number(a.castle)-Number(b.castle);}if(a.remaining===null){return 1;}if(b.remaining===null){return -1;}return a.remaining-b.remaining;});}
