  function adminSubscriptionsHtml(){var mode=state.adminExpiryMode,days=state.adminExpiryDays,rows=adminSubscriptionRows(mode,days),owners=adminSubscriptionOwners(rows);return '<section class="section-card admin-expiry-filter"><h2>متابعة انتهاء الاشتراكات</h2><p>اختر حالة الاشتراك لعرض العملاء المطابقين، كل عميل مرة واحدة مع عدد قلاعه.</p><div class="admin-expiry-controls"><label class="form-row"><span class="label">الحالة</span><select id="adminExpiryMode" class="field"><option value="expired" '+(mode==='expired'?'selected':'')+'>منتهي بالفعل</option><option value="due" '+(mode==='due'?'selected':'')+'>سينتهي خلال</option><option value="missing" '+(mode==='missing'?'selected':'')+'>غير مسجل</option></select></label><label id="adminExpiryDaysRow" class="form-row" '+(mode==='due'?'':'hidden')+'><span class="label">عدد الأيام القادمة</span><input id="adminExpiryDays" class="field" type="number" inputmode="numeric" min="0" max="3650" value="'+days+'"></label></div><button id="adminExpiryApply" class="small-btn admin-expiry-apply" type="button" '+(mode==='due'?'':'hidden')+'>⌕ عرض النتائج</button><div class="admin-expiry-presets" '+(mode==='due'?'':'hidden')+'>'+[1,2,5,10].map(function(value){return '<button type="button" data-expiry-days="'+value+'" class="'+(days===value?'active':'')+'">'+value+' يوم</button>';}).join('')+'</div><div class="admin-expiry-summary"><b>'+owners.length+' عميل</b><span>'+rows.length+' قلعة مطابقة</span></div></section><div class="admin-expiry-list">'+(owners.length?owners.map(adminSubscriptionCardHtml).join(''):'<div class="empty">لا يوجد عملاء مطابقون لهذا الفلتر.</div>')+'</div>';}
  function adminArchiveMatches(scope,identifier){var id=String(identifier||'');return state.adminArchiveDirectory.filter(function(group){return scope==='telegram'?group[0]===id:group[1].some(function(row){return row.id===id;});});}
  function adminArchiveTotals(){return {owners:state.adminArchiveDirectory.length,castles:state.adminArchiveDirectory.reduce(function(total,group){return total+group[1].length;},0)};}
  function adminArchiveCredentialStatus(row){if(row.flags&2){return 'تحتاج إدخال بيانات الدخول لاحقًا';}return row.flags&1?'بيانات الدخول محفوظة':'تحتاج مراجعة قبل الاسترجاع';}
  function adminArchiveRowHtml(owner,row){var restorable=!!(row.flags&1),selected=!!state.adminArchiveSelected[row.id],previousEnd=adminExpiryText(row.previousEnd)||'غير مسجل';return '<div class="admin-archive-castle '+(restorable?'':'blocked')+'"><label class="admin-archive-select"><input type="checkbox" data-archive-castle="'+esc(row.id)+'" data-archive-owner="'+esc(owner)+'" '+(selected?'checked':'')+' '+(restorable?'':'disabled')+'><span><b>🏰 '+esc(row.id)+'</b><small>آخر انتهاء مسجل: '+esc(previousEnd)+'</small></span></label><strong class="archive-credential-state '+((row.flags&2)||!restorable?'missing':'saved')+'">'+esc(adminArchiveCredentialStatus(row))+'</strong>'+(restorable?'<details class="archive-credentials"><summary>إدخال بريد وكلمة مرور IGG الآن — اختياري</summary><div><input class="field" type="email" inputmode="email" autocomplete="off" autocapitalize="none" spellcheck="false" maxlength="200" data-archive-email="'+esc(row.id)+'" placeholder="IGG email"><input class="field" type="password" autocomplete="new-password" autocapitalize="none" spellcheck="false" maxlength="200" data-archive-password="'+esc(row.id)+'" placeholder="IGG password"></div><p>اتركهما فارغين لتجديد القلعة الآن وإضافة البيانات لاحقًا من تعديل القلعة.</p></details>':'<p class="archive-unrestorable">ملفات الاسترجاع غير مكتملة؛ لا يمكن تحديد هذه القلعة.</p>')+'</div>';}
